<script setup lang="ts">
const token=ref(''),status=ref<'idle'|'sending'|'sent'|'error'>('idle'),error=ref(''),turnstile=ref<HTMLElement|null>(null)
onMounted(async()=>{try{const {turnstileSiteKey}=await $fetch<{turnstileSiteKey:string}>('/api/contact/config'); const render=()=>{const w=window as any;if(w.turnstile&&turnstile.value)w.turnstile.render(turnstile.value,{sitekey:turnstileSiteKey,theme:'light',size:'flexible',callback:(v:string)=>token.value=v})};const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=render;document.head.appendChild(script)}catch{error.value='The contact form is temporarily unavailable.'}})
async function submit(event:Event){status.value='sending';error.value='';const form=event.currentTarget as HTMLFormElement;try{await $fetch('/api/contact',{method:'POST',body:{...Object.fromEntries(new FormData(form)),turnstileToken:token.value}});status.value='sent';form.reset()}catch(c:any){status.value='error';error.value=c?.data?.statusMessage||'Unable to send this message.'}}
</script>
<template><div><section class="jumbotron container"><h1>Reach out to me!</h1></section><section class="contact-links"><div class="container text-center"><h3>Contact Link</h3><br><div class="row justify-center"><div class="col-4"><a class="contact-card" href="https://github.com/karshh"><img class="brand-img" src="/assets/img/GitHub.png" alt="GitHub"></a></div><div class="col-4"><a class="contact-card" href="#contact-form"><img class="brand-img" src="/assets/img/Mail.png" alt="Contact form"></a></div><div class="col-4"><a class="contact-card" href="https://www.linkedin.com/in/karshsharma/"><img class="brand-img" src="/assets/img/LinkedIn.png" alt="LinkedIn"></a></div></div></div></section><section class="form-section"><div class="container"><form class="form" @submit.prevent="submit"><h4 id="contact-form"><strong>Contact Form</strong></h4><br><div v-for="name in ['name','email','subject']" :key="name" class="form-group"><label :for="name">{{name.charAt(0).toUpperCase()+name.slice(1)}}</label><input :id="name" class="form-control" :name="name" :type="name==='email'?'email':'text'" required></div><div class="form-group"><label for="message">Message</label><textarea id="message" class="form-control" name="message" rows="4" required maxlength="5000" /></div><div class="honeypot" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><div ref="turnstile" class="turnstile" aria-label="Anti-spam verification"></div><p v-if="error" class="error" role="alert">{{error}}</p><button class="btn btn-dark" :disabled="!token||status==='sending'">{{status==='sending'?'Sending…':'Submit'}}</button><p v-if="status==='sent'">✓ Sent.</p></form></div></section></div></template>
